#!/bin/bash
# Автообновление сервера: вся логика в deploy/update.sh (п. 5 списка улучшений).
# Этот файл остаётся точкой входа для таймера fitnes-update.
exec bash /opt/fitnes/deploy/update.sh "$@"
# Ниже — только для перехода со старой версии этого файла: прежний скрипт, обновив код командой git reset,
# дочитывает файл с той же позиции (байт 1349). Поэтому длина всего, что выше строки «cd deploy», не меняется,
# а хвост повторяет конец прежней версии. Новым запускам до него не дойти: exec выше.
#
cd deploy
if docker compose up -d --build; then
  echo "$new" > "$DEPLOYED"
  echo "$(date -Is) готово"
else
  # Если не собрался ИИ-сервер (профиль ai), CRM всё равно обновляем; полную сборку повторим в следующий раз
  echo "$(date -Is) ОШИБКА сборки, обновляю только CRM"
  docker compose up -d --build app worker
fi
docker image prune -f >/dev/null
exit 0
